package com.example.shelflife;
import android.text.InputType;
import android.widget.*;
import androidx.appcompat.app.AlertDialog;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
final class PasswordDialog {
 static void change(AppDatabase db,long id,String current,String next,String confirmation){if(next==null||next.length()<8||next.trim().isEmpty())throw new IllegalArgumentException("Use at least 8 characters");if(!next.equals(confirmation))throw new IllegalArgumentException("New passwords do not match");if(next.equals(current))throw new IllegalArgumentException("Choose a different password");db.runInTransaction(()->{Staff s=db.productDao().staff(id);if(s==null||!Passwords.verify(current,s.salt,s.passwordHash))throw new IllegalArgumentException("Current password is incorrect");s.salt=Passwords.salt();s.passwordHash=Passwords.hash(next,s.salt);db.productDao().update(s);});}
 static void show(MainActivity a,AppDatabase db,long id){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);int pad=Math.round(24*a.getResources().getDisplayMetrics().density);box.setPadding(pad,0,pad,0);EditText[] fields=new EditText[3];String[] labels={"Current password","New password","Confirm new password"};for(int i=0;i<3;i++){EditText e=new EditText(a);e.setHint(labels[i]);e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setSingleLine(true);box.addView(e,new LinearLayout.LayoutParams(-1,-2));fields[i]=e;}TextView error=new TextView(a);box.addView(error);AlertDialog d=new MaterialAlertDialogBuilder(a).setTitle("Change password").setView(box).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String old=fields[0].getText().toString(),next=fields[1].getText().toString(),confirm=fields[2].getText().toString();d.setCancelable(false);d.getButton(-1).setEnabled(false);d.getButton(-2).setEnabled(false);for(EditText e:fields)e.setEnabled(false);Auth.IO.execute(()->{try{if(Auth.session(a)!=id)throw new IllegalArgumentException("Sign in again");change(db,id,old,next,confirm);a.runOnUiThread(()->{if(a.isDestroyed())return;d.dismiss();Toast.makeText(a,"Password updated",Toast.LENGTH_SHORT).show();});}catch(Exception ex){a.runOnUiThread(()->{if(a.isDestroyed())return;error.setText(ex instanceof IllegalArgumentException?ex.getMessage():"Could not save. Try again.");d.setCancelable(true);d.getButton(-1).setEnabled(true);d.getButton(-2).setEnabled(true);for(EditText e:fields)e.setEnabled(true);});}});}));d.show();}
}
